s("ripples_homeCardBody", "Three quiet minutes with a few others. No words, no score.", "Under the Home card. Calm; no pressure.", "మరికొందరితో కలిసి మూడు ప్రశాంతమైన నిమిషాలు. మాటలు లేవు, స్కోర్ లేదు.", "Marikondari tho kalisi moodu prashaanthamaina nimishaalu. Maatalu levu, score ledu.", hi="कुछ और लोगों के साथ तीन शांत मिनट। न कोई बात, न कोई स्कोर।", hl="Kuch aur logon ke saath teen shaant minute. Na koi baat, na koi score.")
s("ripples_breatheTogether", "Breathe together", "Room button: invite the room's live members to a 3-minute co-breath.", "కలిసి శ్వాస తీసుకుందాం", "Kalisi breathe cheddaam", hi="साथ में साँस लें", hl="Saath mein saans lein")
s("ripples_invite", "{name} wants to breathe together · {count}/{capacity}", "In-room banner for 20 s: someone invited the room to Breath Ripples. name = a room pseudonym.", "{name} కలిసి శ్వాస తీసుకోవాలనుకుంటున్నారు · {count}/{capacity}", "{name} kalisi breathe cheyyalanukuntunnaru · {count}/{capacity}", {"name": {"type": "String"}, "count": {"type": "int"}, "capacity": {"type": "int"}}, hi="{name} का साथ में साँस लेने का मन है · {count}/{capacity}", hl="{name} ka saath mein saans lene ka mann hai · {count}/{capacity}")
s("ripples_inviteJoin", "Join", "Banner button: join the room's Breath Ripples invite.", "చేరండి", "Join avvandi", hi="जुड़ें", hl="Join karein")
s("ripples_inviteMine", "Your invite is open · {count}/{capacity}", "Banner for the person who invited the room.", "మీ ఆహ్వానం తెరిచి ఉంది · {count}/{capacity}", "Mee invite open ga undi · {count}/{capacity}", {"count": {"type": "int"}, "capacity": {"type": "int"}}, hi="आपका इनवाइट खुला है · {count}/{capacity}", hl="Aapka invite open hai · {count}/{capacity}")

# ---- lobby -------------------------------------------------------------------------
s("ripples_lobby", "Looking for others to breathe with…", "Lobby while matching (at most 20 s). The pacer already runs.", "కలిసి శ్వాస తీసుకోవడానికి ఇతరుల కోసం చూస్తున్నాం…", "Kalisi breathe cheyadaaniki itharula kosam choostunnaam…", hi="साथ साँस लेने वाले लोग ढूँढे जा रहे हैं…", hl="Saath saans lene wale log dhoondhe ja rahe hain…")
s("ripples_lobbyHint", "Breathe along while you wait. You can leave any time.", "Under the lobby line.", "వేచి ఉన్నప్పుడు కూడా శ్వాసతో పాటు సాగండి. ఎప్పుడైనా వెళ్ళిపోవచ్చు.", "Wait chestunnappudu kooda breath tho paatu saagandi. Eppudaina vellipovachhu.", hi="इंतज़ार के दौरान साथ-साथ साँस लें। इसे कभी भी छोड़ा जा सकता है।", hl="Intezaar ke dauraan saath-saath saans lein. Ise kabhi bhi chhoda ja sakta hai.")
s("ripples_holdHint", "Hold to breathe in, let go to breathe out", "Input hint (hold mode).", "లోపలికి శ్వాసకు పట్టుకోండి, బయటకు వదలడానికి వదిలేయండి", "Lopaliki breathe ki pattukondi, bayataki vadalataaniki vadileyandi", hi="साँस अंदर लेने के लिए दबाकर रखें, बाहर छोड़ने के लिए छोड़ दें", hl="Saans andar lene ke liye daba ke rakhein, bahar chhodne ke liye chhod dein")
s("ripples_tapHint", "Tap to switch between breathing in and out", "Input hint (accessible mode: tap to switch).", "లోపలికి, బయటకు మారడానికి ట్యాప్ చేయండి", "Lopaliki, bayataki maaradaaniki tap cheyandi", hi="साँस अंदर और बाहर के बीच बदलने के लिए टैप करें", hl="Saans andar aur bahar ke beech badalne ke liye tap karein")
s("ripples_breathArea", "Breathing area", "Screen-reader label of the large area you hold (or tap) to breathe.", "శ్వాస ప్రాంతం", "Breathing area", hi="साँस लेने की जगह", hl="Saans lene ki jagah")

# ---- unavailable (always with a solo option; never an error screen) -----------------------
s("ripples_offline", "Breathing together needs a connection. Breathe solo instead?", "PRD 14 Offline state.", "కలిసి శ్వాస తీసుకోవడానికి కనెక్షన్ కావాలి. ఒంటరిగా శ్వాస తీసుకుంటారా?", "Kalisi breathe cheyadaaniki connection kaavali. Solo ga breathe chestaara?", hi="साथ में साँस लेने के लिए कनेक्शन चाहिए। अकेले साँस लें?", hl="Saath mein saans lene ke liye connection chahiye. Akele saans lein?")
s("ripples_paused", "Breath Ripples is resting for a bit. Breathe solo instead?", "Kill switch on (ripples_paused). Calm.", "Breath Ripples కాసేపు విశ్రాంతి తీసుకుంటోంది. ఒంటరిగా శ్వాస తీసుకుంటారా?", "Breath Ripples kaasepu vishraanti teesukuntondi. Solo ga breathe chestaara?", hi="Breath Ripples अभी थोड़ी देर आराम कर रहा है। अकेले साँस लें?", hl="Breath Ripples abhi thodi der aaram kar raha hai. Akele saans lein?")
s("ripples_suspended", "Breathing together is paused for this account right now. You can still breathe on your own.", "The account's social access is paused (sanction). Never says why.", "ఈ ఖాతాకు కలిసి శ్వాస తీసుకోవడం ప్రస్తుతం ఆగింది. మీరు ఒంటరిగా శ్వాస తీసుకోవచ్చు.", "Ee account ki kalisi breathe cheyadam prasthutham aagindi. Meeru solo ga breathe cheyochhu.", hi="इस अकाउंट के लिए साथ में साँस लेना अभी रुका हुआ है। अकेले साँस लेना अब भी मुमकिन है।", hl="Is account ke liye saath mein saans lena abhi ruka hua hai. Akele saans lena ab bhi mumkin hai.")
s("ripples_closed", "This account can't breathe together with others. You can still breathe on your own.", "The account is closed (banned).", "ఈ ఖాతా ఇతరులతో కలిసి శ్వాస తీసుకోలేదు. మీరు ఒంటరిగా శ్వాస తీసుకోవచ్చు.", "Ee account itharula tho kalisi breathe cheyaledu. Meeru solo ga breathe cheyochhu.", hi="इस अकाउंट से दूसरों के साथ साँस लेना मुमकिन नहीं है। अकेले साँस लेना अब भी मुमकिन है।", hl="Is account se doosron ke saath saans lena mumkin nahi hai. Akele saans lena ab bhi mumkin hai.")
s("ripples_guidelines", "The community guidelines come first. Open Rooms to read them, or breathe on your own for now.", "409 guidelines_required: the guidelines are accepted in Rooms.", "ముందుగా కమ్యూనిటీ మార్గదర్శకాలు. వాటిని చదవడానికి Rooms తెరవండి, లేదా ఇప్పటికి ఒంటరిగా శ్వాస తీసుకోండి.", "Mundu community guidelines. Vaatini chadavadaaniki Rooms open cheyandi, leda ippatiki solo ga breathe cheyandi.", hi="पहले कम्युनिटी गाइडलाइंस। उन्हें पढ़ने के लिए रूम खोलें, या अभी अकेले साँस लें।", hl="Pehle community guidelines. Unhein padhne ke liye Rooms kholein, ya abhi ke liye akele saans lein.")
s("ripples_breatheSolo", "Breathe solo", "Opens the Sanctuary's Breathe pacer.", "ఒంటరిగా శ్వాస", "Solo ga breathe", hi="अकेले साँस लें", hl="Akele saans lein")

