s("ripples_settle", "Settle in", "Phase word during the 10 s settle-in before the first breath.", "స్థిరపడండి", "Settle avvandi", hi="सहज हो जाएँ", hl="Sahaj ho jayein")
s("ripples_fade", "Let it fade", "Phase word during the 10 s fade-out after the last breath.", "మెల్లగా ముగియనివ్వండి", "Mellaga mugiyanivvandi", hi="धीरे-धीरे थमने दें", hl="Dheere-dheere thamne dein")
s("ripples_together", "{count, plural, =1{Just you and the ocean} other{{count} people breathing together}}", "Intro line: the people who started this session (never echoes or guides).", "{count, plural, =1{మీరు, ఈ సముద్రం మాత్రమే} other{{count} మంది కలిసి శ్వాస తీసుకుంటున్నారు}}", "{count, plural, =1{Meeru, ee samudram maatrame} other{{count} mandi kalisi breathe chestunnaru}}", INT("count"), hi="{count, plural, =1{बस आप और समंदर} other{{count} लोग साथ साँस ले रहे हैं}}", hl="{count, plural, =1{Bas aap aur samandar} other{{count} log saath saans le rahe hain}}")
s("ripples_echoesJoined", "{count, plural, =1{1 echo joined. It's a recording of a real person who breathed here before.} other{{count} echoes joined. They're recordings of real people who breathed here before.}}", "PRD 14: echoes fill empty seats. Honest: they are recordings, never counted as people.", "{count, plural, =1{1 ప్రతిధ్వని చేరింది. ఇంతకు ముందు ఇక్కడ శ్వాస తీసుకున్న ఒక నిజమైన వ్యక్తి రికార్డింగ్ ఇది.} other{{count} ప్రతిధ్వనులు చేరాయి. ఇంతకు ముందు ఇక్కడ శ్వాస తీసుకున్న నిజమైన వ్యక్తుల రికార్డింగ్‌లు ఇవి.}}", "{count, plural, =1{1 echo join ayyindi. Idi intaku mundu ikkada breathe chesina oka nijamaina vyakti recording.} other{{count} echoes join ayyaayi. Ivi intaku mundu ikkada breathe chesina nijamaina vyaktula recordings.}}", INT("count"), hi="{count, plural, =1{1 गूँज जुड़ी। यह किसी असली इंसान की रिकॉर्डिंग है, जिसने पहले यहाँ साँस ली थी।} other{{count} गूँजें जुड़ीं। ये उन असली लोगों की रिकॉर्डिंग हैं, जिन्होंने पहले यहाँ साँस ली थी।}}", hl="{count, plural, =1{1 echo judi. Ye kisi asli insaan ki recording hai, jisne pehle yahan saans li thi.} other{{count} echoes judi. Ye un asli logon ki recordings hain, jinhone pehle yahan saans li thi.}}")
s("ripples_guides", "{count, plural, =1{A guide light breathes with you.} other{{count} guide lights breathe with you.}}", "Guide lights fill seats while the echo library is small. Never presented as people.", "{count, plural, =1{ఒక గైడ్ వెలుగు మీతో శ్వాస తీసుకుంటుంది.} other{{count} గైడ్ వెలుగులు మీతో శ్వాస తీసుకుంటాయి.}}", "{count, plural, =1{Oka guide light meetho breathe chestundi.} other{{count} guide lights meetho breathe chestaayi.}}", INT("count"), hi="{count, plural, =1{एक गाइड लाइट आपके साथ साँस लेती है।} other{{count} गाइड लाइट आपके साथ साँस लेती हैं।}}", hl="{count, plural, =1{Ek guide light aapke saath saans leti hai.} other{{count} guide lights aapke saath saans leti hain.}}")
s("ripples_solo", "Breathing on your own this time. The ocean still listens.", "PRD 14: no echoes available; a solo pacer.", "ఈసారి మీరు ఒంటరిగా శ్వాస తీసుకుంటున్నారు. సముద్రం ఇంకా వింటోంది.", "Ee saari meeru solo ga breathe chestunnaru. Samudram inka vintondi.", hi="इस बार अकेले साँस चल रही है। समंदर अब भी सुन रहा है।", hl="Is baar akele saans chal rahi hai. Samandar ab bhi sun raha hai.")
s("ripples_linkLost", "You're breathing on your own for a moment.", "PRD 14: the connection dropped; the pacer continues locally. Never an error.", "కాసేపు మీరు ఒంటరిగా శ్వాస తీసుకుంటున్నారు.", "Kaasepu meeru solo ga breathe chestunnaru.", hi="कुछ पल के लिए अकेले साँस चल रही है।", hl="Kuch pal ke liye akele saans chal rahi hai.")
s("ripples_alone", "Keep breathing. The ocean is still here.", "After the rejoin window: the session finishes on this phone, gently.", "శ్వాస కొనసాగించండి. సముద్రం ఇంకా ఇక్కడే ఉంది.", "Breathe continue cheyandi. Samudram inka ikkade undi.", hi="साँस लेते रहें। समंदर अब भी यहीं है।", hl="Saans lete rahein. Samandar ab bhi yahin hai.")
s("ripples_leave", "Leave", "Tooltip of ✕: leave quietly at any time (no penalty, nothing is said to others).", "వెళ్ళిపోండి", "Vellipondi", hi="निकलें", hl="Nikalein")
s("ripples_accessibleMode", "Accessible mode", "Toggle: tap to switch, tones and stronger haptics when in step (on automatically with a screen reader).", "సులభ మోడ్", "Accessible mode", hi="एक्सेसिबल मोड", hl="Accessible mode")
s("ripples_accessibleModeHint", "Tap to switch between in and out. Tones and firmer haptics tell you when you're in step with the others.", "Explains accessible mode. Sync is never a number.", "లోపలికి, బయటకు మారడానికి ట్యాప్ చేయండి. మీరు ఇతరులతో కలిసి ఉన్నప్పుడు టోన్లు, గట్టి హ్యాప్టిక్స్ తెలియజేస్తాయి.", "Lopaliki, bayataki maaradaaniki tap cheyandi. Meeru itharula tho step lo unnappudu tones, konchem gattiga haptics cheptaayi.", hi="अंदर और बाहर के बीच बदलने के लिए टैप करें। जब आप दूसरों के साथ ताल में हों, तो टोन और ज़्यादा मज़बूत वाइब्रेशन यह बताते हैं।", hl="Andar aur bahar ke beech badalne ke liye tap karein. Jab aap doosron ke saath step mein hon, to tones aur zyada firm haptics ye batate hain.")

