s("ripples_pulseFrom", "{name} sent a pulse", "Announced (and shown) when someone pulses.", "{name} పల్స్ పంపారు", "{name} pulse pampaaru", NAME, hi="{name} ने पल्स भेजी", hl="{name} ne pulse bheji")
s("ripples_gestureFrom", "{name} · {gesture}", "Shown by a light and announced: who sent which gesture (gesture = its name).", "{name} · {gesture}", "{name} · {gesture}", STR("name", "gesture"), hi="{name} · {gesture}", hl="{name} · {gesture}")
s("ripples_contactTray", "Send something kind", "Screen-reader label of the pulse + gesture row.", "ఏదైనా మంచిది పంపండి", "Edaina manchidi pampandi", hi="कुछ अपनापन भेजें", hl="Thoda apnapan bhejein")

# ---- a light's sheet (mute / block / report) --------------------------------------------------------------------
s("ripples_mute", "Mute", "Stop this light's pulses, gestures and haptics for you, for this session.", "మ్యూట్", "Mute", hi="म्यूट", hl="Mute")
s("ripples_unmute", "Unmute", "Undo mute.", "అన్‌మ్యూట్", "Unmute", hi="अनम्यूट", hl="Unmute")
s("ripples_block", "Block", "Block this person: never matched again (they aren't told).", "బ్లాక్", "Block", hi="ब्लॉक", hl="Block")
s("ripples_report", "Report", "Report this person (reasons, optional note).", "రిపోర్ట్", "Report", hi="रिपोर्ट", hl="Report")
s("ripples_blocked", "Blocked. You won't be matched together again.", "After block. The other person is never told.", "బ్లాక్ చేశారు. మీరిద్దరూ మళ్ళీ కలవరు.", "Block chesaaru. Meeriddaru malli match avvaru.", hi="ब्लॉक कर दिया गया। आप दोनों का फिर से मैच नहीं होगा।", hl="Block kar diya gaya. Aap dono ka phir se match nahi hoga.")
s("ripples_reported", "Thank you. Someone from Aura will look at it.", "After a report.", "ధన్యవాదాలు. Aura నుండి ఎవరైనా దీన్ని చూస్తారు.", "Thanks. Aura nundi evaraina deenni choostaaru.", hi="शुक्रिया। Aura की टीम से कोई इसे देखेगा।", hl="Shukriya. Aura ki team se koi ise dekhega.")
s("ripples_actionFailed", "That didn't go through. Please try again.", "Mute/block/report failed (connection). No blame.", "అది జరగలేదు. దయచేసి మళ్ళీ ప్రయత్నించండి.", "Adi jaragaledu. Dayachesi malli try cheyandi.", hi="यह नहीं हो पाया। कृपया फिर से कोशिश करें।", hl="Ye nahi ho paya. Please phir se try karein.")

# ---- end ---------------------------------------------------------------------------------------------------------------
s("ripples_endTitle", "That was a few minutes together.", "End screen. Never a score or how well it went.", "ఇది కలిసి గడిపిన కొన్ని నిమిషాలు.", "Idi kalisi gadipina konni nimishaalu.", hi="ये कुछ मिनट साथ में बीते।", hl="Ye kuch minute saath mein beete.")
s("ripples_again", "Breathe again", "End screen: start another session (same entry).", "మళ్ళీ శ్వాస తీసుకుందాం", "Malli breathe cheddaam", hi="फिर से साँस लें", hl="Phir se saans lein")
s("ripples_backToRoom", "Back to room", "End screen (room sessions): back to the room.", "రూమ్‌కి తిరిగి", "Room ki tirigi", hi="रूम पर वापस", hl="Room par wapas")
s("ripples_feelNow", "How do you feel now?", "End screen, optional: opens a check-in (F1).", "ఇప్పుడు ఎలా అనిపిస్తోంది?", "Ippudu ela anipistondi?", hi="अब कैसा लग रहा है?", hl="Ab kaisa lag raha hai?")
s("ripples_echoToggle", "Let my breathing become an echo", "Echo opt-out switch (on by default, per the privacy notice).", "నా శ్వాస ఒక ప్రతిధ్వనిగా మారనివ్వండి", "Naa breathing oka echo ga maaranivvandi", hi="मेरी साँसों को गूँज बनने दें", hl="Meri saanson ko echo banne dein")
s("ripples_echoToggleHint", "An echo keeps only the timing of your breaths, never who you are, so it can't be traced back to you. Turning this off stops future echoes.", "Under the echo switch. Honest about what is kept.", "ప్రతిధ్వని మీ శ్వాస సమయాలను మాత్రమే ఉంచుతుంది, మీరు ఎవరో కాదు, కాబట్టి అది మీ వరకు చేరదు. దీన్ని ఆపితే ఇకపై ప్రతిధ్వనులు రికార్డ్ కావు.", "Echo mee breaths timing maatrame unchutundi, meeru evaro kaadu, kaabatti adi mee varaku raadu. Idi off chesthe inka mundu echoes record kaavu.", hi="गूँज में सिर्फ़ आपकी साँसों की टाइमिंग रहती है, आप कौन हैं यह कभी नहीं, इसलिए इसे आप तक वापस नहीं जोड़ा जा सकता। इसे बंद करने पर आगे से कोई नई गूँज नहीं बनेगी।", hl="Echo mein sirf aapki saanson ki timing rehti hai, aap kaun hain ye kabhi nahi, isliye ise aap tak wapas nahi joda ja sakta. Ise band karne par aage se koi nayi echo nahi banegi.")
